import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Test Flow: Basic Inline Scripts
export const flowWithBasicInlineScripts = Flow(
    {
        $id: Now.ID['test_flow_basic_inline_scripts'],
        name: 'Test - Inline Script Example Basic',
        description: 'Test flow with basic inline scripts',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_trigger_inline_basic'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    () => {
        // Simple string inline script
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_simple_string'], annotation: 'Log with simple string inline script' },
            {
                log_level: 'info',
                log_message: wfa.inlineScript("return 'Hello from inline script!'"),
            }
        )

        // Inline script accessing trigger data
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_trigger_data_script'], annotation: 'Log trigger data from inline script' },
            {
                log_level: 'info',
                log_message: wfa.inlineScript("return 'Incident Number: ' + fd_data.trigger.current.number"),
            }
        )

        // Inline script with conditional logic
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_conditional_script'], annotation: 'Log with conditional inline script' },
            {
                log_level: 'info',
                log_message: wfa.inlineScript(
                    "return fd_data.trigger.current.priority == 1 ? 'High Priority' : 'Normal Priority'"
                ),
            }
        )
    }
)
